{
  "pass": true,
  "issues": [],
  "notes": [
    "Audit của trợ lý sau kiểm tra bản sửa, không phải đánh giá độc lập hay duyệt của người dùng.",
    "Giữ bảy mùa đào, học chữ, bốn môn, canh ba và truyền trường sinh; giảm lời giải thích lặp bằng hành động. Chưa học biến hóa."
  ],
  "canon_delta": {
    "characters": [
      {
        "id": "stone-monkey",
        "name": "Tôn Ngộ Không",
        "position": "Phòng ngủ chung, Tà Nguyệt Tam Tinh Động, rạng sáng sau đêm truyền pháp (năm thứ bảy trong môn)",
        "abilities": [
          "Đọc và viết chữ Hán cơ bản; đọc được bia cổng; viết được chữ 孫",
          "Khí vận được thêm tới bàn chân không gây đau, sau nhiều tháng luyện có kiểm soát",
          "Đã được truyền đạo trường sinh (khẩu quyết về tinh khí thần), chưa luyện thành"
        ],
        "resources": [
          "Bảy hạt đào trên bậu cửa sổ"
        ],
        "knowledge": [
          "Bốn môn thuật, lưu, tĩnh, động không cho trường sinh",
          "Luật tự đặt cũ sai một nửa: không phải cấm đưa khí đi, mà phải có bờ"
        ],
        "relationships": [
          "Đồng môn thư sinh gầy dạy chữ, đổi lấy gánh hộ nước",
          "Đồng môn mắng vì làm thầy giận"
        ]
      },
      {
        "id": "subhuti",
        "action": "Hỏi bảy năm, đưa bốn môn, gõ đầu ba cái, đóng cửa giữa; canh ba truyền đạo trường sinh sau khi hỏi 'vì biết hay vì hiểu'"
      },
      {
        "id": "senior-brother",
        "state": "Mười chín năm vẫn quét sân",
        "knowledge": [
          "'Bao giờ quét sân mà không nghĩ tới chuyện học phép' mới tới lúc"
        ]
      },
      {
        "id": "scholar-disciple",
        "name": "Đồng môn thư sinh gầy (không tên)",
        "identity": [
          "Trẻ, gầy, trắng, ít nói, đọc sách đêm"
        ],
        "action": "Dạy Ngộ Không chữ; được Tổ sư dạy môn kinh sách"
      }
    ],
    "events": [
      {
        "order": 82,
        "event": "Năm đầu làm việc vặt: quét sân, gánh nước, nhổ cỏ; hạt đào đầu tiên",
        "time": "Năm thứ nhất trong môn"
      },
      {
        "order": 83,
        "event": "Học chữ với đồng môn thư sinh; đọc được bia cổng",
        "time": "Năm thứ hai trong môn"
      },
      {
        "order": 84,
        "event": "Nghe giảng về nước có bờ; đổi cách luyện; khí nới ra chút ít",
        "time": "Năm thứ hai – ba trong môn"
      },
      {
        "order": 85,
        "event": "Buổi giảng năm thứ bảy: nhảy múa vì hiểu; từ chối bốn môn; bị gõ đầu ba cái",
        "time": "Cuối hè năm thứ bảy trong môn"
      },
      {
        "order": 86,
        "event": "Tự giải câu đố; canh ba vào cửa sau; được truyền đạo trường sinh",
        "time": "Đêm cùng ngày"
      }
    ],
    "seeds": [
      {
        "id": "S16",
        "state": "paid_off",
        "source": "“Biết là của sách. Hiểu là của ngươi.”",
        "fact": "Phân biệt tri thức biết trước và hiểu biết của nhân vật"
      },
      {
        "id": "S11",
        "state": "advanced",
        "fact": "Hạt đào đếm năm song song với vạch trên vách ở Hoa Quả Sơn"
      },
      {
        "id": "S18",
        "state": "introduced",
        "optional": true,
        "source": "“Biết là của sách.”",
        "fact": "Lời Tổ sư có thể chỉ là ẩn dụ; không xác nhận ông biết chuyển sinh"
      },
      {
        "id": "S08",
        "state": "revised",
        "fact": "Không cấm vận khí đi xa; thử chậm theo đường và dừng khi đau"
      }
    ]
  }
}

{
  "pass": true,
  "issues": [],
  "notes": [
    "Audit của trợ lý sau kiểm tra bản sửa, không phải đánh giá độc lập hay duyệt của người dùng.",
    "Chuỗi mười tới mười một hạt đào nay có thêm mùa hè được nêu rõ; cân đẩu cuối thu, quyết định không về cuối đông.",
    "Phân thân có cảnh truyền và luyện trước lần dùng chương 18. Ràng buộc về thăm là lựa chọn của nhân vật, không lệnh cấm mới."
  ],
  "canon_delta": {
    "characters": [
      {
        "id": "stone-monkey",
        "name": "Tôn Ngộ Không",
        "position": "Sân Tà Nguyệt Tam Tinh Động, sáng cuối đông năm thứ mười một trong môn",
        "abilities": [
          "Đạo trường sinh: thân bền, ít đói/ngủ, nghe xa nhanh; vận khí theo đường gánh nước",
          "Địa sát bảy mươi hai biến: đã thành; luyện từ lá, sỏi, dế tới chim sẻ (chim sẻ có vệt lông vàng nâu trên ngực)",
          "Cân đẩu vân: mười vạn tám nghìn dặm một cái lộn; đã học cách dừng, đổi hướng, lộn ngắn",
          "Thân ngoại thân: ít thân làm vài việc riêng; nhiều thân chỉ lệnh nhóm đơn giản, vượt mức gây đau đầu và kiệt khí"
        ],
        "knowledge": [
          "Ba tai: lôi tai, âm hỏa, bí phong, năm trăm năm một lần; trường sinh không phải bất tử"
        ],
        "resources": [
          "Mười một hạt đào"
        ],
        "state": "Thầy cho tự quyết về thăm; chọn ở lại tới qua đông vì ưu tiên luyện chắc và tính sai thời điểm tai họa",
        "relationships": [
          "Một số đồng môn ghen vì được truyền riêng",
          "Không kể với thư sinh gầy để tránh khoe"
        ]
      },
      {
        "id": "subhuti",
        "action": "Cảnh báo ba tai; dạy địa sát bảy mươi hai biến và cân đẩu vân"
      },
      {
        "id": "senior-brother",
        "action": "Quét sân hộ ba ngày khi Ngộ Không đi lạc"
      },
      {
        "id": "scholar-disciple",
        "state": "Không được kể chuyện truyền riêng; không hỏi thêm"
      }
    ],
    "events": [
      {
        "order": 87,
        "event": "Ba năm luyện đạo trường sinh; thân thể đổi chậm",
        "time": "Năm thứ tám – mười trong môn"
      },
      {
        "order": 88,
        "event": "Tổ sư cảnh báo ba tai; Ngộ Không chọn địa sát bảy mươi hai biến",
        "time": "Cuối hè năm thứ mười"
      },
      {
        "order": 89,
        "event": "Luyện biến hóa: lần hỏng nửa người hóa đá; ba tháng mới biến thành chim sẻ",
        "time": "Năm thứ mười – mười một"
      },
      {
        "order": 90,
        "event": "Đồng môn ghen; Ngộ Không không khoe",
        "time": "Năm thứ mười một"
      },
      {
        "order": 91,
        "event": "Bò mây ba dặm trước Tổ sư lúc hoàng hôn; được dạy cân đẩu vân",
        "time": "Cuối thu năm thứ mười một"
      },
      {
        "order": 92,
        "event": "Lộn quá đà đi lạc ba ngày; tập dần làm chủ",
        "time": "Đông năm thứ mười một"
      },
      {
        "order": 93,
        "event": "Đêm lộn lên đỉnh núi nhìn về phía đông, không về",
        "time": "Cuối đông năm thứ mười một"
      },
      {
        "event": "Sau mùa đào thứ mười một học và luyện thân ngoại thân; trước cuối đông hỏi về thăm, được tự quyết nhưng chọn ở lại",
        "time": "Năm thứ mười một trong môn"
      }
    ],
    "seeds": [
      {
        "id": "S19",
        "state": "introduced",
        "source": "“Ba tai. Năm trăm năm một lần.”",
        "fact": "Nỗi sợ trường sinh không phải bất tử; gắn với con số năm trăm"
      },
      {
        "id": "S20",
        "state": "introduced",
        "source": "“Không phải lúc nào cũng phải đánh.”",
        "fact": "Lý do chọn bảy mươi hai biến là bảo vệ đàn"
      },
      {
        "id": "S21",
        "state": "introduced",
        "fact": "Lòng đã ở nhà; đồng môn ghen — mầm cho việc rời môn"
      },
      {
        "id": "S24",
        "state": "introduced",
        "fact": "Sai lầm cho rằng tai họa phải chờ mình rời môn; luyện phân thân đặt giới hạn cho trận sau"
      }
    ]
  }
